CREATE OR REPLACE FUNCTION private.capture_current_report_publication()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare sc public.report_corpus_scopes;created timestamptz;begin
 if new.current_source_run_id is not null and new.state='completed' and new.controls->>'technical_checks_passed'='true' then
  select * into sc from public.report_corpus_scopes where source_run_id=new.current_source_run_id;
  select created_at into created from public.historical_report_runs where id=new.current_source_run_id;
  perform private.store_current_report_publication(to_jsonb(new),to_jsonb(sc),created);
 end if;return new;
end $function$

CREATE OR REPLACE FUNCTION public.sync_current_v2_generation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare pair public.analysis_parallel_reports;st text;ec text;begin
 if tg_table_name='analysis_parallel_reports' then pair=new;st=new.state;ec=new.error_code;
 else select * into pair from public.analysis_parallel_reports where run_id=new.id;st=new.status;ec=new.error_code;end if;
 if pair.current_source_run_id is null then return new;end if;
 if st in('blocked','billing_uncertain','authorization_expired','invalid_output') then
  update public.historical_report_runs set status='failed',error_code=coalesce(ec,st),last_error=coalesce(ec,st),locked_by=null,lease_until=null,completed_at=now(),updated_at=now() where id=pair.current_source_run_id and status in('queued','running','retry');
 elsif pair.derived_report is not null and st in('completed','needs_review') then
  update public.historical_report_runs set status='completed',error_code=ec,last_error=ec,locked_by=null,lease_until=null,completed_at=now(),updated_at=now() where id=pair.current_source_run_id and status in('queued','running','retry');
 end if;return new;end $function$

CREATE OR REPLACE FUNCTION public.guard_parallel_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin if tg_op='DELETE' and current_user in('postgres','supabase_admin') and current_setting('home.retention_maintenance',true)='on' then return old;end if;
 if tg_op='DELETE' then raise exception 'IMMUTABLE_HISTORY';end if;
 if old.derived_report is not null or old.raw_response is not null or old.imported_derivative_id is not null then raise exception 'IMMUTABLE_HISTORY';end if;
 if (to_jsonb(new)-array['state','error_code','raw_response','original_report','derived_report','corrections','controls','statistics','usage','generated_at'])<>(to_jsonb(old)-array['state','error_code','raw_response','original_report','derived_report','corrections','controls','statistics','usage','generated_at']) then raise exception 'IMMUTABLE_SOURCE';end if;return new;
end $function$

CREATE OR REPLACE FUNCTION private.retention_publication_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.review_corpus_policy;sc public.report_corpus_scopes;begin
 if current_setting('home.retention_maintenance',true)='on' then return new;end if;
 select * into p from public.review_corpus_policy where id for share;
 if not p.enabled then return new;end if;
 select * into sc from public.report_corpus_scopes where source_run_id=new.current_source_run_id;
 if sc.source_run_id is null or sc.policy_epoch<>p.epoch then raise exception 'RETAINED_CURRENT_SOURCE_REQUIRED';end if;
 if new.state in('completed','needs_review') and (sc.stale or sc.fingerprint<>public.review_corpus_fingerprint(new.establishment_id)) then
  new.state='blocked';new.error_code='CORPUS_CHANGED_DURING_GENERATION';new.derived_report=null;
 end if;return new;
end $function$

CREATE OR REPLACE FUNCTION public.retention_write_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare p public.review_corpus_policy;begin
 if current_user in('postgres','supabase_admin') and current_setting('home.retention_maintenance',true)='on' then return null;end if;
 select * into p from public.review_corpus_policy where id for share;
 if p.paused then raise exception 'RETENTION_TRANSITION_ACTIVE';end if;
 if tg_table_schema||'.'||tg_table_name=any(p.retired_relations) then raise exception 'REPORT_PIPELINE_RETIRED';end if;
 if p.ingestions_paused and tg_table_name in('reviews','review_translations','review_provider_payloads','review_reply_drafts','initial_import_jobs','review_sync_jobs','sync_runs','establishment_snapshots') then raise exception 'RETENTION_INGESTION_PAUSED';end if;
 return null;
end $function$
